data.CSS:
:root { --ink: #1a1a1a; --muted: #5b6470; --rule: #e6e8eb; --accent: #0b5fff; }
* { box-sizing: border-box; }
body { margin: 0; color: var(--ink); background: #fff;
  font: 16px/1.65 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
.shio-container { max-width: 44rem; margin: 0 auto; padding: 0 1.25rem; }
.shio-masthead { border-bottom: 1px solid var(--rule); padding: 1.25rem 0; margin-bottom: 2.5rem; }
.shio-masthead a { color: var(--ink); text-decoration: none; font-weight: 600; }
h1 { font-size: 2rem; line-height: 1.2; margin: 0 0 .5rem; }
.shio-summary { color: var(--muted); font-size: 1.125rem; margin: 0 0 1.5rem; }
.shio-byline { color: var(--muted); font-size: .875rem; margin: 0 0 2rem; }
.shio-body :is(p, ul, ol) { margin: 0 0 1.25rem; }
.shio-body code { background: #f4f5f7; padding: .1em .35em; border-radius: 3px; }
a { color: var(--accent); }
footer { border-top: 1px solid var(--rule); margin-top: 3rem; padding: 1.5rem 0; color: var(--muted); }
